class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.3
        Supports :meth:`fileno` by lazily backing the stream with a real
        pipe, so code that passes this object (or a wrapper around it) to
        :class:`subprocess.Popen` as ``stdout``/``stderr`` works instead of
        raising ``io.UnsupportedOperation``.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._fd_relay: tuple[int, int, threading.Thread] | None = None

    def flush(self) -> None:
        super().flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return super().write(b)

    def fileno(self) -> int:
        if self._fd_relay is None:
            read_fd, write_fd = os.pipe()

            def relay() -> None:
                while True:
                    try:
                        chunk = os.read(read_fd, io.DEFAULT_BUFFER_SIZE)
                    except OSError:
                        break
                    if not chunk:
                        break
                    self.write(chunk)

            thread = threading.Thread(target=relay, daemon=True)
            thread.start()
            self._fd_relay = (read_fd, write_fd, thread)

        return self._fd_relay[1]

    def close_fd_relay(self) -> None:
        """Stop the pipe relay thread started by :meth:`fileno`, if any.

        .. versionadded:: 8.3.3
        """
        if self._fd_relay is not None:
            read_fd, write_fd, thread = self._fd_relay
            self._fd_relay = None
            os.close(write_fd)
            thread.join()
            os.close(read_fd)

